import { chromium } from 'playwright';
import { readFileSync } from 'node:fs';

const BASE = process.env.BASE_URL || 'http://localhost:5212';
const assert = (condition, message) => {
  if (!condition) throw new Error(message);
};

// A real near-end position generated by the engine. White has pushed five
// marbles off and can win with the two-marble NE push at points 12 and 6.
const PREWIN = JSON.parse(
  readFileSync(new URL('./fixtures/abalone-prewin.json', import.meta.url), 'utf8'),
);

const cjkParts = (text) => text.match(/[\u3400-\u9fff]+/g) ?? [];
const latinWords = (text) => text.match(/[A-Za-z]+/g) ?? [];
const assertEnglishOnly = (text, where) => {
  const parts = cjkParts(text);
  assert(parts.every((part) => part === '中文'), `unexpected Chinese in ${where}: ${parts.join(' | ')}`);
};
const assertChineseOnly = (text, where) => {
  const words = latinWords(text);
  assert(
    words.every((word) => word === 'English'),
    `unexpected English in ${where}: ${words.join(' | ')}`,
  );
};

const browser = await chromium.launch({ channel: 'chrome', headless: true });
const context = await browser.newContext();
const page = await context.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('console', (message) => {
  if (message.type() === 'error') errors.push(message.text());
});
page.on('pageerror', (error) => errors.push(String(error)));

await page.addInitScript(() => {
  localStorage.setItem('familyarcade.lang', 'en');
});
await page.goto(BASE, { waitUntil: 'networkidle' });
await page.evaluate(() => {
  localStorage.removeItem('familyarcade.abalone.save');
  localStorage.removeItem('familyarcade.abalone.record');
});
await page.reload({ waitUntil: 'networkidle' });

// English home must not contain Chinese apart from the language switch.
assertEnglishOnly(await page.locator('body').innerText(), 'English home');

// Hot-seat: one marble, one direction button, then undo and hint.
await page.getByRole('button', { name: /Two players, one screen/ }).click();
assertEnglishOnly(await page.locator('body').innerText(), 'English game');
await page.locator('.ab-point[data-index="13"]').click();
assert((await page.locator('.ab-point.selected').count()) === 1, 'single selection failed');
assert((await page.locator('.direction-button:not(:disabled)').count()) >= 1, 'no legal directions');
await page.locator('.direction-button[data-dir="SE"]').click();
await page.waitForTimeout(120);
assert(
  (await page.locator('.ab-point[data-index="21"]').getAttribute('data-color')) === 'B',
  'marble did not move',
);
assert((await page.locator('.turn-copy').innerText()).includes('White to move'), 'turn did not pass');

await page.getByRole('button', { name: /Undo/ }).click();
await page.waitForTimeout(120);
assert(
  (await page.locator('.ab-point[data-index="13"]').getAttribute('data-color')) === 'B',
  'undo did not restore the marble',
);
assert(
  (await page.locator('.ab-point[data-index="21"]').getAttribute('data-color')) === '',
  'undo left the destination occupied',
);

await page.getByRole('button', { name: /Hint/ }).click();
await page.waitForSelector('.ab-point.hint-source', { timeout: 30000 });
assert((await page.locator('.ab-point.hint-source').count()) >= 1, 'hint source missing');
assert((await page.locator('.toast').innerText()).length > 0, 'hint reason missing');

// AI replies to a human move and the game autosaves.
await page.getByRole('button', { name: /Home/ }).click();
await page.getByRole('button', { name: /Play the computer/ }).click();
await page.getByRole('button', { name: /Begin/ }).click();
await page.locator('.ab-point[data-index="13"]').click();
await page.locator('.direction-button[data-dir="SE"]').click();
await page.waitForFunction(
  () => {
    const text = document.querySelector('.turn-copy strong')?.textContent ?? '';
    return text.includes('Computer') || text.includes('Thinking');
  },
  null,
  { timeout: 5000 },
);
await page.waitForFunction(
  () => (document.querySelector('.turn-copy strong')?.textContent ?? '').includes('Your turn'),
  null,
  { timeout: 30000 },
);
assert(
  (await page.locator('.match-middle').innerText()).includes('2 moves played'),
  'AI did not make the second move',
);

await page.reload({ waitUntil: 'networkidle' });
assert(
  await page.getByRole('button', { name: /Continue last game/ }).isVisible(),
  'continue card missing after autosave',
);
await page.getByRole('button', { name: /Continue last game/ }).click();
assert(
  (await page.locator('.match-middle').innerText()).includes('2 moves played'),
  'resumed game lost its move count',
);

// Seeded near-end position: a real winning push updates the family record.
await page.evaluate((state) => {
  localStorage.setItem(
    'familyarcade.abalone.save',
    JSON.stringify({ version: 1, state, mode: 'local', level: 'normal', savedAt: Date.now() }),
  );
}, PREWIN);
await page.reload({ waitUntil: 'networkidle' });
await page.getByRole('button', { name: /Continue last game/ }).click();
await page.locator('.ab-point[data-index="12"]').click();
await page.locator('.ab-point[data-index="6"]').click();
assert((await page.locator('.ab-point.selected').count()) === 2, 'two-marble selection failed');
await page.locator('.direction-button[data-dir="NE"]').click();
await page.waitForSelector('.result-banner', { timeout: 5000 });
assert((await page.locator('.result-banner').innerText()).includes('White wins'), 'white win not shown');
const savedRecord = await page.evaluate(() =>
  JSON.parse(localStorage.getItem('familyarcade.abalone.record') || '{}'),
);
assert(savedRecord.games === 1 && savedRecord.winsW === 1, 'record not updated');

// Record screen is reachable and shows the game.
await page.getByRole('button', { name: /Home/ }).click();
await page.getByRole('button', { name: /Family record/ }).click();
assert(await page.locator('.stats-top').isVisible(), 'stats screen missing');
assert((await page.locator('.recent-list').innerText()).includes('White wins'), 'recent game missing');

// Mobile layout is usable.
const mobile = await browser.newPage({
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 2,
});
await mobile.addInitScript(() => {
  localStorage.setItem('familyarcade.lang', 'en');
});
await mobile.goto(BASE, { waitUntil: 'networkidle' });
assert(await mobile.locator('h1').isVisible(), 'mobile home missing');
await mobile.getByRole('button', { name: /Two players, one screen/ }).click();
assert(await mobile.locator('.ab-board').isVisible(), 'mobile board missing');
await mobile.locator('.ab-point[data-index="13"]').click();
assert((await mobile.locator('.ab-point.selected').count()) === 1, 'mobile selection failed');

// Chinese UI contains no Latin words except the language switch.
const zh = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await zh.addInitScript(() => {
  localStorage.setItem('familyarcade.lang', 'zh');
});
await zh.goto(BASE, { waitUntil: 'networkidle' });
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese home');

await zh.getByRole('button', { name: /和电脑下一局/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese setup');
await zh.locator('.back').click();

await zh.getByRole('button', { name: /^规则/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese rules');
await zh.getByRole('button', { name: /关闭/ }).click();

await zh.getByRole('button', { name: /局域网对战/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese LAN lobby');
await zh.locator('.back').click();

await zh.getByRole('button', { name: /家庭战绩/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese record');
await zh.locator('.back').click();

await zh.getByRole('button', { name: /两人同屏/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese game');

await zh.evaluate((state) => {
  localStorage.setItem(
    'familyarcade.abalone.save',
    JSON.stringify({ version: 1, state, mode: 'local', level: 'normal', savedAt: Date.now() }),
  );
}, PREWIN);
await zh.reload({ waitUntil: 'networkidle' });
await zh.getByRole('button', { name: /继续上局/ }).click();
await zh.locator('.ab-point[data-index="12"]').click();
await zh.locator('.ab-point[data-index="6"]').click();
await zh.locator('.direction-button[data-dir="NE"]').click();
await zh.waitForSelector('.result-banner', { timeout: 5000 });
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese game over');
await zh.getByRole('button', { name: /主页/ }).click();
await zh.getByRole('button', { name: /家庭战绩/ }).click();
assertChineseOnly(await zh.locator('body').innerText(), 'Chinese record with data');

assert(errors.length === 0, `console errors: ${errors.join(' | ')}`);
await browser.close();
console.log('E2E OK — hot-seat, move, undo, hint, AI, autosave, seeded win, record, mobile, bilingual');
